package com.moveinsync.roster.service;
import com.fasterxml.jackson.databind.ObjectMapper; import com.moveinsync.roster.domain.Employee; import com.moveinsync.roster.repository.*; import org.junit.jupiter.api.Test; import java.util.Optional; import static org.mockito.Mockito.*; import org.springframework.jdbc.core.JdbcTemplate; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import static org.junit.jupiter.api.Assertions.*;
class EmployeeSyncServiceTest {
 @Test void staleAndDuplicateVersionsAreIgnored() {EmployeeRepository er=mock(EmployeeRepository.class);OutboxRepository or=mock(OutboxRepository.class);Employee e=new Employee("acme","E1","Asha","a@example.com","M1","BLR","+919876543210",7);when(er.findLocked("acme","E1")).thenReturn(Optional.of(e));var s=new EmployeeSyncService(er,or,new ObjectMapper(),mock(JdbcTemplate.class),new RosterMetrics(new SimpleMeterRegistry()));var event=new EmployeeEvent("acme","E1",EmployeeEvent.EventType.UPDATE,6,"Asha","a@example.com","M1","BLR","+919876543210");assertEquals("IGNORED",s.apply(event).status());assertEquals(7,e.getSourceVersion());verify(or,never()).save(any());}
 @Test void duplicateVersionIsANoOp() {EmployeeRepository er=mock(EmployeeRepository.class);OutboxRepository or=mock(OutboxRepository.class);Employee e=new Employee("acme","E1","Asha","a@example.com","M1","BLR","+919876543210",2);when(er.findLocked("acme","E1")).thenReturn(Optional.of(e));var s=new EmployeeSyncService(er,or,new ObjectMapper(),mock(JdbcTemplate.class),new RosterMetrics(new SimpleMeterRegistry()));var result=s.apply(new EmployeeEvent("acme","E1",EmployeeEvent.EventType.UPDATE,2,"Changed","a@example.com","M1","HYD","+919876543210"));assertEquals("IGNORED",result.status());assertEquals("Asha",e.getName());verify(or,never()).save(any());}
 @Test void hrUpdateDoesNotOverwriteTransportOwnedFields() {EmployeeRepository er=mock(EmployeeRepository.class);OutboxRepository or=mock(OutboxRepository.class);Employee e=new Employee("acme","E1","Asha","a@example.com","M1","BLR","+919876543210",1);e.updateTransport("Metro Gate",true);when(er.findLocked("acme","E1")).thenReturn(Optional.of(e));var s=new EmployeeSyncService(er,or,new ObjectMapper(),mock(JdbcTemplate.class),new RosterMetrics(new SimpleMeterRegistry()));s.apply(new EmployeeEvent("acme","E1",EmployeeEvent.EventType.UPDATE,2,"Asha Rao","a@example.com","M1","HYD","+919876543210"));assertEquals("Metro Gate",e.getPickupPoint());assertTrue(e.isSpecialAssistance());}
 @Test void deactivationPreservesEmployeeProfileAndAdvancesVersion() {EmployeeRepository er=mock(EmployeeRepository.class);OutboxRepository or=mock(OutboxRepository.class);Employee e=new Employee("acme","E1","Asha","a@example.com","M1","BLR","+919876543210",3);e.updateTransport("Metro Gate",true);when(er.findLocked("acme","E1")).thenReturn(Optional.of(e));var s=new EmployeeSyncService(er,or,new ObjectMapper(),mock(JdbcTemplate.class),new RosterMetrics(new SimpleMeterRegistry()));var result=s.apply(new EmployeeEvent("acme","E1",EmployeeEvent.EventType.DEACTIVATE,4,null,null,null,null,null));assertEquals("APPLIED",result.status());assertFalse(e.isActive());assertEquals("Asha",e.getName());assertEquals("Metro Gate",e.getPickupPoint());assertEquals(4,e.getSourceVersion());}
 @Test void malformedPhoneIsRejectedAtServiceBoundary() {EmployeeRepository er=mock(EmployeeRepository.class);OutboxRepository or=mock(OutboxRepository.class);var s=new EmployeeSyncService(er,or,new ObjectMapper(),mock(JdbcTemplate.class),new RosterMetrics(new SimpleMeterRegistry()));var result=s.apply(new EmployeeEvent("acme","E1",EmployeeEvent.EventType.CREATE,1,"Asha","a@example.com","M1","BLR","not-a-phone"));assertEquals("REJECTED",result.status());verify(er,never()).save(any());}

}
